package main

import (
	"crypto/subtle"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"log"
	"net/http"
	"os"
	"sync/atomic"
	"time"

	_ "github.com/mattn/go-sqlite3"
)

var (
	db          *sql.DB
	adminToken  []byte
	requestCtr  atomic.Int64 // Track requests per window for rate limiting
	maxRequests int64 = 100
)

// resetCounter resets the rate limit counter every minute
func resetCounter() {
	for {
		time.Sleep(60 * time.Second)
		requestCtr.Store(0)
	}
}

// rateLimitMiddleware prevents brute-force attacks on admin endpoints
func rateLimitMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		current := requestCtr.Add(1)
		// Reject if over the rate limit
		if current > maxRequests {
			http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
			return
		}
		next(w, r)
	}
}

// handleAdminAction performs privileged database operations
func handleAdminAction(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Admin-Token")
	if token == "" {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	tokenBytes, err := hex.DecodeString(token)
	if err != nil {
		http.Error(w, "Invalid token format", http.StatusBadRequest)
		return
	}

	// Constant-time comparison to prevent timing attacks
	if subtle.ConstantTimeCompare(tokenBytes, adminToken) != 1 {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	userID := r.URL.Query().Get("user_id")
	if userID == "" {
		http.Error(w, "Missing user_id", http.StatusBadRequest)
		return
	}

	// Safe parameterized query
	var username string
	err = db.QueryRow("SELECT username FROM users WHERE id = ?", userID).Scan(&username)
	if err != nil {
		http.Error(w, "User not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	// Use encoding/json to ensure the username is properly escaped in output
	resp := map[string]string{
		"username": username,
		"status":   "active",
	}
	if err := json.NewEncoder(w).Encode(resp); err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
}

// handlePublicLookup is an unauthenticated endpoint for user lookups
func handlePublicLookup(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("name")
	if name == "" || len(name) > 64 {
		http.Error(w, "Invalid name parameter", http.StatusBadRequest)
		return
	}

	var count int
	// Safe parameterized query
	err := db.QueryRow("SELECT COUNT(*) FROM users WHERE username = ?", name).Scan(&count)
	if err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	// Use encoding/json to ensure proper output encoding
	resp := map[string]bool{
		"exists": count > 0,
	}
	if err := json.NewEncoder(w).Encode(resp); err != nil {
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
}

func main() {
	var err error
	db, err = sql.Open("sqlite3", "./app.db")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	// Initialize admin token from environment
	tokenHex := os.Getenv("ADMIN_TOKEN")
	if tokenHex == "" {
		log.Fatal("ADMIN_TOKEN environment variable required")
	}
	adminToken, err = hex.DecodeString(tokenHex)
	if err != nil {
		log.Fatal("Invalid ADMIN_TOKEN format")
	}

	go resetCounter()

	http.HandleFunc("/api/public/lookup", handlePublicLookup)
	http.HandleFunc("/api/admin/action", rateLimitMiddleware(handleAdminAction))

	log.Println("Server starting on :8443")
	log.Fatal(http.ListenAndServeTLS(":8443", "cert.pem", "key.pem", nil))
}
